176	bool EventListenerPhysicsContact::init()
177	{
178	    auto func = [this](EventCustom* event) -> void
179	    {
180	        onEvent(event);
181	    };
182	    
183	    return EventListenerCustom::init(PHYSICSCONTACT_EVENT_NAME, func);
184	}
