#include "physics/CCPhysicsCollisionPair.h"
#if CC_USE_PHYSICS

#include <cmath>
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

PhysicsCollisionPair::PhysicsCollisionPair()
: _arbiter(nullptr)
, _shapeA(nullptr)
, _shapeB(nullptr)
, _valid(false)
, _ignored(false)
{
}

PhysicsCollisionPair::~PhysicsCollisionPair()
{
}

bool PhysicsCollisionPair::init(cpArbiter* arbiter)
{
    if (arbiter == nullptr)
    {
        return false;
    }

    cpShape* cpShapeA = nullptr;
    cpShape* cpShapeB = nullptr;
    cpArbiterGetShapes(arbiter, &cpShapeA, &cpShapeB);

    if (cpShapeA == nullptr || cpShapeB == nullptr)
    {
        return false;
    }

    PhysicsShape* shapeA = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeA));
    PhysicsShape* shapeB = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeB));

    if (shapeA == nullptr || shapeB == nullptr)
    {
        return false;
    }

    _arbiter = arbiter;
    _shapeA = shapeA;
    _shapeB = shapeB;
    _valid = true;
    _ignored = false;

    return true;
}

void PhysicsCollisionPair::update(cpArbiter* arbiter)
{
    if (!init(arbiter))
    {
        invalidate();
    }
}

void PhysicsCollisionPair::invalidate()
{
    _arbiter = nullptr;
    _valid = false;
}

PhysicsShape* PhysicsCollisionPair::getShapeA() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return nullptr;
    }

    return _shapeA;
}

PhysicsShape* PhysicsCollisionPair::getShapeB() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return nullptr;
    }

    return _shapeB;
}

PhysicsBody* PhysicsCollisionPair::getBodyA() const
{
    PhysicsShape* shape = getShapeA();
    return shape == nullptr ? nullptr : shape->getBody();
}

PhysicsBody* PhysicsCollisionPair::getBodyB() const
{
    PhysicsShape* shape = getShapeB();
    return shape == nullptr ? nullptr : shape->getBody();
}

int PhysicsCollisionPair::getContactCount() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return 0;
    }

    return cpArbiterGetCount(_arbiter);
}

CollisionPoint PhysicsCollisionPair::getContactPoint(int index) const
{
    CollisionPoint point = {};

    int count = getContactCount();
    if (index < 0 || index >= count)
    {
        return point;
    }

    point.pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(_arbiter, index));
    point.pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(_arbiter, index));
    point.normal = PhysicsHelper::cpv2point(cpArbiterGetNormal(_arbiter));
    point.depth = PhysicsHelper::cpfloat2float(cpArbiterGetDepth(_arbiter, index));

    // Chipmunk only exposes the accumulated impulse for the whole arbiter, so it is
    // shared out evenly between the contact points.
    float share = 1.0f / static_cast<float>(count);
    point.normalImpulse = getTotalNormalImpulse() * share;
    point.tangentImpulse = getTotalTangentImpulse() * share;

    return point;
}

void PhysicsCollisionPair::getContactPoints(CollisionPoint* outPoints, int* outCount) const
{
    int count = 0;

    if (outPoints != nullptr)
    {
        count = getContactCount();
        for (int i = 0; i < count; ++i)
        {
            outPoints[i] = getContactPoint(i);
        }
    }

    if (outCount != nullptr)
    {
        *outCount = count;
    }
}

Vec2 PhysicsCollisionPair::getContactNormal() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return Vec2::ZERO;
    }

    return PhysicsHelper::cpv2point(cpArbiterGetNormal(_arbiter));
}

float PhysicsCollisionPair::getTotalNormalImpulse() const
{
    Vec2 normal = getContactNormal();
    if (normal.isZero())
    {
        return 0.0f;
    }

    return std::fabs(getTotalImpulse().dot(normal));
}

float PhysicsCollisionPair::getTotalTangentImpulse() const
{
    Vec2 normal = getContactNormal();
    if (normal.isZero())
    {
        return 0.0f;
    }

    return std::fabs(getTotalImpulse().dot(normal.getPerp()));
}

Vec2 PhysicsCollisionPair::getTotalImpulse() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return Vec2::ZERO;
    }

    return PhysicsHelper::cpv2point(cpArbiterTotalImpulse(_arbiter));
}

float PhysicsCollisionPair::getKineticEnergy() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return 0.0f;
    }

    return PhysicsHelper::cpfloat2float(cpArbiterTotalKE(_arbiter));
}

float PhysicsCollisionPair::getRestitution() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return 0.0f;
    }

    return PhysicsHelper::cpfloat2float(cpArbiterGetRestitution(_arbiter));
}

void PhysicsCollisionPair::setRestitution(float restitution)
{
    if (_arbiter == nullptr || !_valid)
    {
        return;
    }

    cpArbiterSetRestitution(_arbiter, restitution);
}

float PhysicsCollisionPair::getFriction() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return 0.0f;
    }

    return PhysicsHelper::cpfloat2float(cpArbiterGetFriction(_arbiter));
}

void PhysicsCollisionPair::setFriction(float friction)
{
    if (_arbiter == nullptr || !_valid)
    {
        return;
    }

    cpArbiterSetFriction(_arbiter, friction);
}

Vec2 PhysicsCollisionPair::getSurfaceVelocity() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return Vec2::ZERO;
    }

    return PhysicsHelper::cpv2point(cpArbiterGetSurfaceVelocity(_arbiter));
}

void PhysicsCollisionPair::setSurfaceVelocity(const Vec2& velocity)
{
    if (_arbiter == nullptr || !_valid)
    {
        return;
    }

    cpArbiterSetSurfaceVelocity(_arbiter, PhysicsHelper::point2cpv(velocity));
}

bool PhysicsCollisionPair::isFirstContact() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return false;
    }

    return cpArbiterIsFirstContact(_arbiter) != 0;
}

bool PhysicsCollisionPair::isRemoval() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return false;
    }

    return cpArbiterIsRemoval(_arbiter) != 0;
}

bool PhysicsCollisionPair::isSensor() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return false;
    }

    cpShape* cpShapeA = nullptr;
    cpShape* cpShapeB = nullptr;
    cpArbiterGetShapes(_arbiter, &cpShapeA, &cpShapeB);

    if (cpShapeA != nullptr && cpShapeGetSensor(cpShapeA) != 0)
    {
        return true;
    }

    return cpShapeB != nullptr && cpShapeGetSensor(cpShapeB) != 0;
}

void PhysicsCollisionPair::ignore()
{
    if (_arbiter == nullptr || !_valid)
    {
        return;
    }

    cpArbiterIgnore(_arbiter);
    _ignored = true;
}

bool PhysicsCollisionPair::isIgnored() const
{
    return _ignored;
}

float PhysicsCollisionPair::computeSeparatingVelocity() const
{
    Vec2 normal = getContactNormal();
    if (normal.isZero())
    {
        return 0.0f;
    }

    return computeRelativeVelocity().dot(normal);
}

float PhysicsCollisionPair::computeOverlap() const
{
    int count = getContactCount();
    float overlap = 0.0f;

    for (int i = 0; i < count; ++i)
    {
        float depth = std::fabs(PhysicsHelper::cpfloat2float(cpArbiterGetDepth(_arbiter, i)));
        if (depth > overlap)
        {
            overlap = depth;
        }
    }

    return overlap;
}

Vec2 PhysicsCollisionPair::computeRelativeVelocity() const
{
    if (_arbiter == nullptr || !_valid)
    {
        return Vec2::ZERO;
    }

    cpShape* cpShapeA = nullptr;
    cpShape* cpShapeB = nullptr;
    cpArbiterGetShapes(_arbiter, &cpShapeA, &cpShapeB);

    if (cpShapeA == nullptr || cpShapeB == nullptr)
    {
        return Vec2::ZERO;
    }

    cpBody* bodyA = cpShapeGetBody(cpShapeA);
    cpBody* bodyB = cpShapeGetBody(cpShapeB);

    if (bodyA == nullptr || bodyB == nullptr)
    {
        return Vec2::ZERO;
    }

    cpVect centre = PhysicsHelper::point2cpv(computeContactCenter());
    Vec2 velocityA = PhysicsHelper::cpv2point(cpBodyGetVelocityAtWorldPoint(bodyA, centre));
    Vec2 velocityB = PhysicsHelper::cpv2point(cpBodyGetVelocityAtWorldPoint(bodyB, centre));

    return velocityB - velocityA;
}

Vec2 PhysicsCollisionPair::computeContactCenter() const
{
    int count = getContactCount();
    if (count <= 0)
    {
        return Vec2::ZERO;
    }

    Vec2 sum = Vec2::ZERO;
    for (int i = 0; i < count; ++i)
    {
        Vec2 pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(_arbiter, i));
        Vec2 pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(_arbiter, i));
        sum += (pointA + pointB) * 0.5f;
    }

    return sum / static_cast<float>(count);
}

NS_CC_END

#endif // CC_USE_PHYSICS

